gone() { local x=${1#/dev/} i; for ((i=0;i<50;i++)); do [[ -e /sys/block/$x/loop/backing_file ]] || return 0; /usr/bin/sleep 0.1; done; echo "  $x still attached"; }
att() { /usr/sbin/losetup "$@"; settle; }
detach() { local d; for d; do /usr/sbin/losetup -d $d; gone $d; done; }
cd $RT; seed img 65536
r zero-n hexdump -n 40 /dev/zero
r zero-skip-C hexdump -C -s 7 -n 21 /dev/zero
r null hexdump /dev/null
r null-C hexdump -C /dev/null
r tty-then-zero hexdump -n 4 /dev/tty /dev/zero
d=$(att -f --show img)
r loop-C hexdump -C -n 64 -s 512 $d
r loop-tail hexdump -C -s 65520 $d
printf '0 16 linear %s 0\n16 16 error\n' $d | /usr/sbin/dmsetup create --noudevsync rf-err || echo SETUP-FAILED
m=$(/usr/sbin/dmsetup info -c --noheadings -o minor rf-err); echo "fixture dm-$m"
r dm-eio hexdump -C -s 8160 /dev/dm-$m
r dm-eio-n hexdump -n 16 -s 8184 /dev/dm-$m
/usr/sbin/dmsetup remove --noudevsync rf-err; detach $d
